import { VoxelBehavior } from "./VoxelBehaviors";
export class VoxelBehaviorsRegister {
    static behaviors = new Map();
    static register(data) {
        if (!data.inherits && data.type != "dve_default")
            data.inherits = "dve_default";
        if (data.inherits) {
            const otherType = this.get(data.inherits);
            for (const key in otherType) {
                if (key == "type" || key == "inherits")
                    continue;
                if (!data[key] && otherType[key]) {
                    data[key] = otherType[key];
                }
            }
        }
        this.behaviors.set(data.type, new VoxelBehavior(data));
    }
    static get(type) {
        const behavior = this.behaviors.get(type);
        if (!behavior)
            throw new Error(`Voxel behavior ${type} does not exist`);
        return behavior;
    }
}
